class Solution:
    def countGoodRotations(self, nums: list[int]) -> int:
        n = len(nums)
        m = n // 2
        total_sum = sum(nums)

        # prefix[i] = sum of nums[0:i]
        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i+1] = prefix[i] + nums[i]

        def window_sum(start, size):
            """Sum of 'size' consecutive elements starting at index 'start' (0-indexed),
            with wrap-around if start + size > n."""
            if start + size <= n:
                return prefix[start + size] - prefix[start]
            else:
                # Wrap around: from start to end + from beginning
                return (prefix[n] - prefix[start]) + (prefix[start + size - n] - prefix[0])

        count = 0
        for k in range(n):
            # For rotation k, the first half of the rotated array starts at nums[k]
            first_half_sum = window_sum(k, m)
            # Second half sum = total_sum - first_half_sum
            # Rotation is good if first_half_sum > second_half_sum, i.e.,
            # 2 * first_half_sum > total_sum
            if 2 * first_half_sum > total_sum:
                count += 1

        return count

MOD = 10**9 + 7

def fib(n):
    # fast doubling, returns (Fib(n), Fib(n+1)) with Fib(0)=0, Fib(1)=1
    if n == 0:
        return (0, 1)
    else:
        a, b = fib(n >> 1)
        c = (a * (2 * b - a)) % MOD
        d = (a * a + b * b) % MOD
        if n & 1:
            return (d, (c + d) % MOD)
        else:
            return (c, d)

class Solution:
    def countGoodStrings(self, n: int) -> int:
        if n == 0:
            return 0
        fib_n, _ = fib(n)  # Fib(n) with Fib(1)=1
        return (2 * fib_n) % MOD

