                 (a[1][0] * b[0][1] + a[1][1] * b[1][1]) % MOD]
            ]

        def mat_pow(mat, exp):
            res = [[1, 0], [0, 1]]
            base = mat
            while exp > 0:
                if exp & 1:
                    res = mat_mul(res, base)
                base = mat_mul(base, base)
                exp >>= 1
            return res

